let y = 3;
console.log(y++);  // 3 — вернуло СТАРОЕ значение, потом y стало 4
console.log(y);    // 4

let z = 3;
console.log(++z);  // 4 — сначала z стал 4, потом вернулось новое значение

// В цикле for разница не важна, там используют x++ просто как 'увеличить на 1'

const age = 20;
const hasLicense = true;

// && — оба условия должны быть истинны:
if (age >= 18 && hasLicense) {
  console.log("Можно водить");
}

// || — достаточно одного истинного:
const isWeekend = false;
const isHoliday = true;
if (isWeekend || isHoliday) {
  console.log("Можно отдыхать");
}

// ! — инверсия:
console.log(!true);   // false
console.log(!false);  // true

let name = null;
let displayName = name || "Гость";
console.log(displayName);  // Гость — null falsy, взята правая часть

// Ловушка || с числом 0:
let count = 0;
let display = count || 10;
console.log(display);      // 10 — а должно быть 0! || 'съел' ноль

// Безопасная альтернатива ?? — реагирует только на null/undefined:
let display2 = count ?? 10;
console.log(display2);     // 0 — ноль это настоящее значение

